const TOOL_NAME = 'users_get_many';
const MAX_IDS = 5;

const usersGetManyTool = {
  name: TOOL_NAME,
  description:
    'Look up multiple users by id in a single batch call. Returns one line per ' +
    'requested id in the order they were provided. Ids that are not present in ' +
    'the user store are marked as missing rather than failing the entire batch.',
  inputSchema: {
    type: 'object',
    properties: {
      user_ids: {
        type: 'array',
        items: {type: 'string'},
        minItems: 1,
        maxItems: MAX_IDS,
        uniqueItems: true,
        description:
          'User ids to look up. Must be a non-empty array of unique strings ' +
          `with at most ${MAX_IDS} entries.`
      }
    },
    required: ['user_ids'],
    additionalProperties: false
  }
};

function validateArgs(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Arguments must be a JSON object');
  }

  const providedKeys = Object.keys(args);
  const allowed = new Set(['user_ids']);
  const extra = providedKeys.filter((k) => !allowed.has(k));
  if (extra.length > 0) {
    throw new Error(
      `Unexpected field(s): ${extra.join(', ')}. Only "user_ids" is allowed.`
    );
  }

  if (!providedKeys.includes('user_ids')) {
    throw new Error('Missing required field: "user_ids"');
  }

  const {user_ids} = args;

  if (!Array.isArray(user_ids)) {
    throw new Error('"user_ids" must be an array');
  }
  if (user_ids.length === 0) {
    throw new Error('"user_ids" must contain at least one entry');
  }
  if (user_ids.length > MAX_IDS) {
    throw new Error(`"user_ids" must contain at most ${MAX_IDS} entries`);
  }

  const seen = new Set();
  for (let i = 0; i < user_ids.length; i++) {
    const id = user_ids[i];
    if (typeof id !== 'string') {
      throw new Error(`"user_ids[${i}]" must be a string`);
    }
    if (seen.has(id)) {
      throw new Error(`Duplicate user id in "user_ids": "${id}"`);
    }
    seen.add(id);
  }
}

export async function listTools() {
  return [usersGetManyTool];
}

export async function callTool(name, args) {
  if (name !== TOOL_NAME) {
    throw new Error(`Unknown tool: "${name}"`);
  }

  validateArgs(args || {});

  const lines = args.user_ids.map((id) => {
    const record = users[id];
    return record ? `${id}: ${record.name}` : `${id}: not found`;
  });

  return {
    content: [{type: 'text', text: lines.join('\n')}]
  };
}

