import {listTools, callTool} from './server.mjs';

const tools = await listTools();
console.log('listTools count:', tools.length);
console.log('tool name:', tools[0].name);
console.log('required:', tools[0].inputSchema.required);
console.log('maxItems:', tools[0].inputSchema.user_ids.maxItems);
console.log('uniqueItems:', tools[0].inputSchema.user_ids.uniqueItems);

const ok = await callTool('users_get_many', {user_ids:['u1','missing','u3']});
